INSERT INTO "cast_slot" ("scene_key", "key", "title", "binding_kind", "character_key", "role_ref", "gender_binding", "age_binding", "social_status", "relation_note", "address_rule", "count_min", "count_max", "note", "sort") VALUES ('scene.family.before_distribution', 'member', 'Пришедший взрослый член семьи', 'procedural_resident', NULL, NULL, 'runtime_resident', 'Взрослый житель; точный возраст из выбранной семьи.', 'Член двора с хотя бы одним ребёнком, у порога минимального пайка.', 'Приходит просить за свой двор, знает о других нуждающихся, не говорит от их имени.', 'К председателю обращается уважительно; реплики не требуют имени, отчества и грамматического рода.', 1, 1, NULL, 10);
INSERT INTO "cast_slot" ("scene_key", "key", "title", "binding_kind", "character_key", "role_ref", "gender_binding", "age_binding", "social_status", "relation_note", "address_rule", "count_min", "count_max", "note", "sort") VALUES ('scene.family.before_distribution', 'memory_member', 'Взрослый голос того же двора при позднем возврате', 'procedural_resident', NULL, NULL, 'runtime_resident', 'Доступный взрослый родственник при позднем возврате; возраст берётся из партии.', 'Тот же двор или родственная ветвь, действительно пережившая исход Эпохи I.', 'Вспоминает фактический выбор председателя; не подставляется чужая семья.', 'К председателю уважительное «вы»; строка нейтральна к полу говорящего.', 1, 1, NULL, 30);
